-- Выполни это в Supabase: SQL Editor -> New query -> Run
-- v6: создаёт/обновляет таблицу books, Storage bucket book-covers и заполняет библиотеку твоими книгами.
-- ВАЖНО: строка delete from public.books удалит старые демо-книги и заменит их списком ниже.

create table if not exists public.books (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  title text not null,
  author text not null,
  genre text not null default 'Детективы',
  status text not null default 'Прочитано',
  is_favorite boolean not null default false,
  read_date date,
  cover_url text,
  spine_color text default '#8f5c45',
  review text not null,
  quote text,
  rating_total numeric(3,1),
  rating_plot numeric(3,1),
  rating_characters numeric(3,1),
  rating_style numeric(3,1),
  rating_ending numeric(3,1)
);

alter table public.books
  alter column rating_total type numeric(3,1) using rating_total::numeric,
  alter column rating_plot type numeric(3,1) using rating_plot::numeric,
  alter column rating_characters type numeric(3,1) using rating_characters::numeric,
  alter column rating_style type numeric(3,1) using rating_style::numeric,
  alter column rating_ending type numeric(3,1) using rating_ending::numeric;

alter table public.books drop constraint if exists books_rating_total_check;
alter table public.books drop constraint if exists books_rating_plot_check;
alter table public.books drop constraint if exists books_rating_characters_check;
alter table public.books drop constraint if exists books_rating_style_check;
alter table public.books drop constraint if exists books_rating_ending_check;

alter table public.books add constraint books_rating_total_check check (rating_total is null or rating_total between 0 and 5);
alter table public.books add constraint books_rating_plot_check check (rating_plot is null or rating_plot between 0 and 5);
alter table public.books add constraint books_rating_characters_check check (rating_characters is null or rating_characters between 0 and 5);
alter table public.books add constraint books_rating_style_check check (rating_style is null or rating_style between 0 and 5);
alter table public.books add constraint books_rating_ending_check check (rating_ending is null or rating_ending between 0 and 5);

alter table public.books enable row level security;

drop policy if exists "Public books are readable" on public.books;
drop policy if exists "Authenticated users can insert books" on public.books;
drop policy if exists "Authenticated users can update books" on public.books;
drop policy if exists "Authenticated users can delete books" on public.books;

create policy "Public books are readable"
  on public.books
  for select
  using (true);

create policy "Authenticated users can insert books"
  on public.books
  for insert
  to authenticated
  with check (true);

create policy "Authenticated users can update books"
  on public.books
  for update
  to authenticated
  using (true)
  with check (true);

create policy "Authenticated users can delete books"
  on public.books
  for delete
  to authenticated
  using (true);

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'book-covers',
  'book-covers',
  true,
  2097152,
  array['image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do update set
  public = true,
  file_size_limit = 2097152,
  allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp'];

drop policy if exists "Book covers are publicly readable" on storage.objects;
drop policy if exists "Authenticated users can upload book covers" on storage.objects;
drop policy if exists "Authenticated users can update book covers" on storage.objects;
drop policy if exists "Authenticated users can delete book covers" on storage.objects;

create policy "Book covers are publicly readable"
  on storage.objects
  for select
  using (bucket_id = 'book-covers');

create policy "Authenticated users can upload book covers"
  on storage.objects
  for insert
  to authenticated
  with check (bucket_id = 'book-covers');

create policy "Authenticated users can update book covers"
  on storage.objects
  for update
  to authenticated
  using (bucket_id = 'book-covers')
  with check (bucket_id = 'book-covers');

create policy "Authenticated users can delete book covers"
  on storage.objects
  for delete
  to authenticated
  using (bucket_id = 'book-covers');

-- Удаляем старые демо-книги и записываем твой список.
delete from public.books;

insert into public.books (title, author, genre, status, is_favorite, read_date, cover_url, spine_color, review, quote, rating_total, rating_plot, rating_characters, rating_style, rating_ending)
values
  ('Убийство Роджера Экройда', 'А. Кристи', 'Детективы', 'Прочитано', true, '2026-01-17', 'covers/ubiystvo-rodzhera-ekroyda.svg', '#b64c5b', 'Главный восторг — финальный твист: убийцей оказывается именно тот, кому доверяешь роль рассказчика и помощника в расследовании. Доктор выглядит почти образцовой жертвой обстоятельств, поэтому до самого конца подозрения обходят его стороной. За счёт этого развязка срабатывает особенно сильно и делает роман одним из самых впечатляющих у Кристи.', 'Самый надёжный рассказчик иногда скрывает больше всех.', 5, 5, 4.5, 5, 5),
  ('Игра в убийство', 'А. Кристи', 'Детективы', 'Прочитано', true, '2026-02-18', 'covers/igra-v-ubiystvo.svg', '#cf6f3f', 'Очень цепляет сам замысел: герои играют в убийство, и именно в разгар этой игры случается настоящее преступление. Особенно понравилось восстанавливать картину по кусочкам — по чужим словам, случайным наблюдениям и мелочам, которые постепенно складываются в цельное объяснение. Это детектив, где атмосфера игры отлично работает на напряжение.', 'Игра заканчивается ровно в тот момент, когда становится настоящей.', 4.5, 4.5, 4, 4.5, 4.5),
  ('Убийство в “Восточном экспрессе”', 'А. Кристи', 'Детективы', 'Прочитано', true, '2026-04-02', 'covers/ubiystvo-v-vostochnom-ekspresse.svg', '#2f5f95', 'Даже зная твист после фильма, книга всё равно впечатляет. В прозе история ощущается насыщеннее: допросы каждого пассажира напряжённее, детали работают тоньше, а сам Пуаро здесь особенно обаятелен — тщеславный, но удивительно деликатный. В итоге роман понравился заметно больше экранизации.', 'Иногда правда едет в одном вагоне сразу с десятком версий.', 4.5, 4.5, 4.5, 5, 4.5),
  ('Большая четверка', 'А. Кристи', 'Детективы', 'Прочитано', true, '2026-01-20', 'covers/bolshaya-chetverka.svg', '#7d4638', 'Понравилось, что здесь Пуаро и Гастингс впервые действительно ходят по краю и оказываются в настоящей опасности. Особенно запомнился четвертый участник Большой четверки — мастер перевоплощений, который будто всё время где-то рядом, но его неизменно упускают из виду. Отдельный плюс за эффектный ход с «братом Пуаро» и усами: это ружьё выстреливает очень красиво.', 'Опаснее всего враг, которого видишь каждый раз новым лицом.', 4.5, 4, 4.5, 4, 4.5),
  ('Загадка Ситтафорда', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-03-10', 'covers/zagadka-sittaforda.svg', '#8d5a9e', 'У романа очень уютная и при этом тревожная атмосфера: метель, снег, маленькие городки и почти невозможное совпадение в основе тайны. Элемент спиритизма хорошо работает именно как инструмент загадочности, даже без веры в него. Отдельно понравилась невеста главного подозреваемого — за её преданностью, острым умом и настойчивостью наблюдать было не менее интересно, чем за самой интригой.', 'Снег заметает следы, но делает тайну только заметнее.', 4, 4, 4, 4.5, 4),
  ('Тайна желтой комнаты', 'Г. Леру', 'Детективы', 'Прочитано', false, '2026-03-16', 'covers/tayna-zheltoy-komnaty.svg', '#d8a23d', 'Сильнее всего цепляют старт и сам сеттинг: невозможное покушение, странное молчание свидетелей и почти мистическое исчезновение преступника буквально на глазах преследователей. Детектив держит в напряжении за счёт замкнутого пространства и ощущения неразрешимой головоломки. Ближе к финалу интерес немного проседает, а развязке хотелось бы большей изящности.', 'Самая закрытая комната прячет не дверь, а объяснение.', 4, 4.5, 3.5, 4, 3.5),
  ('Убийства по алфавиту', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-01-25', 'covers/ubiystva-po-alfavitu.svg', '#3a6f6a', 'Запомнился приём с двумя рассказчиками: он тонко направляет подозрение и заставляет самого читателя додумывать лишнее. Особенно интересно наблюдать, как две линии постепенно сходятся и усиливают тревогу. В итоге книга хорошо играет именно на восприятии и самообмане читателя.', 'Иногда подозрение растёт не из фактов, а из способа рассказа.', 4, 4, 3.5, 4, 4),
  ('Смерть в облаках', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-04-27', 'covers/smert-v-oblakah.svg', '#5d4d9e', 'Понравилось, как подробно показаны судьбы всех пассажиров, которых задело убийство в самолёте. Интересно было наблюдать за Пуаро, который здесь не просто уверен в себе, а почти оказывается в тупике и даже теряет самообладание. Единственное разочарование — линия с записной книжкой кажется недоработанной, но финальное объяснение всё равно оставляет хорошее впечатление.', 'Даже на высоте правда всё равно ищет место для посадки.', 4, 4, 4, 4, 4),
  ('Свидание со смертью', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-05-11', 'covers/svidanie-so-smertyu.svg', '#b06d3c', 'Книга ощущается чуть камернее и короче других романов о Пуаро, почти как небольшая история между большими делами. Но внутри у неё очень тёплая и сильная линия: семья здесь покрывает друг друга не из злого умысла, а из любви и страха потерять близких. Финал с его почти неожиданным хэппи-эндом оставляет особенно приятное послевкусие.', 'Иногда самая запутанная ложь рождается из любви, а не из вины.', 4, 4, 4, 3.5, 4.5),
  ('Смерть в день рождения', 'Н. Марш', 'Детективы', 'Прочитано', false, '2026-03-05', 'covers/smert-v-den-rozhdeniya.svg', '#884c60', 'Понравились развитие Анелиды и хрупкость Ричарда, который искренне хочет поступить правильно, но не справляется с ситуацией. Хорошо работает и то, что почти сразу несколько человек получают мотив после смерти мисс Беллами. Убийца тоже оставляет сильное впечатление: его можно понять по-человечески, хотя это вовсе не оправдывает его поступок.', 'Хрупкие люди порой ломают судьбы не хуже сильных.', 3.5, 3.5, 4, 3.5, 3.5),
  ('Смерть лорда Эдвера', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-02-12', 'covers/smert-lorda-edvera.svg', '#2d6f83', 'С самого начала интрига строится на почти невозможном убийстве, и это хорошо держит внимание. Особенно удачна героиня, которая прямо говорит о желании убить мужа и тем самым сама загоняет себя под подозрение. Главный интерес здесь — в противоречии между тем, что все видят, и тем, что физически не должно было произойти.', 'Самое подозрительное признание не всегда бывает самым честным.', 3.5, 3.5, 3.5, 3.5, 4),
  ('Немой свидетель / Безмолвный свидетель', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-04-30', 'covers/nemoy-svidetel-bezmolvnyy-svidetel.svg', '#98473a', 'Очень нравится, как Пуаро здесь меняет маски и буквально жонглирует ролями, вытягивая из людей нужную информацию. Интересен и сам способ расследования: жертвы уже нет, вещественных улик почти нет, а значит всё держится на остатках свидетельств и наблюдательности. Минус в том, что ближе к финалу убийца угадывается слишком рано.', 'Когда улик почти нет, личина становится лучшим инструментом следствия.', 3.5, 3.5, 3.5, 4, 3),
  ('Горе невинным', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-02-15', 'covers/gore-nevinnym.svg', '#6d7543', 'Сильнее всего здесь работает сама семейная ситуация: внезапно всплывшая правда переворачивает жизнь людей, которые уже успели смириться с прошлым. Особенно интересны персонажи — это не кровные родственники, а приёмные дети, поэтому каждый связан с остальными по-своему и каждый переживает происходящее по-разному. Из-за этого роман воспринимается не только как детектив, но и как психологическая семейная драма.', 'Чужая правда способна расколоть даже давно сложившуюся семью.', 3.5, 3.5, 4, 3.5, 3.5),
  ('Убийство на поле для гольфа', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-01-15', 'covers/ubiystvo-na-pole-dlya-golfa.svg', '#704f91', 'Понравилось, как мимолётное знакомство Гастингса в поезде позже неожиданно становится важным для развязки. Хорошо сработал и твист с двумя сёстрами: до последнего кажется, что речь идёт об одной женщине, из-за чего подозрения ходят по ложному кругу. Отдельно запомнился Жиро — именно потому, что его методы кажутся чуждыми на фоне более тонкой логики Пуаро.', 'Пока один ищет следы в земле, другой замечает их в людях.', 3.5, 3.5, 3.5, 3.5, 4),
  ('Тайна Голубого поезда', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-01-31', 'covers/tayna-golubogo-poezda.svg', '#3f5f91', 'Больше всего здесь сработала развязка: убийцами оказываются именно те, кого почти не рассматриваешь всерьёз. Всё внимание естественно уходит на жениха убитой и графа-мошенника, поэтому финал становится действительно неожиданным. Книга не идеальна, но как детективная ловушка работает хорошо.', 'Иногда настоящий мотив тихо едет в другом купе.', 3.5, 3.5, 3, 3.5, 4),
  ('Загадочное происшествие в Стайлзе', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-01-13', 'covers/zagadochnoe-proisshestvie-v-staylze.svg', '#b75c3f', 'Очень приятна химия между Гастингсом и Пуаро — именно она придаёт расследованию живость и шарм. Понравилось и то, как легко самой поддаться всеобщему мнению и начать подозревать Инглторпа, потому что улики против него складываются слишком уж удобно. Роман хорошо показывает, как убедительно может выглядеть самая простая версия.', 'Слишком удобный виновник почти всегда заслуживает второго взгляда.', 3.5, 3.5, 4, 3.5, 3.5),
  ('Убийство в Месопотамии', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-02-24', 'covers/ubiystvo-v-mesopotamii.svg', '#53725b', 'Запомнился эмоциональный нарратив Эми: благодаря ей история воспринимается теплее и человечнее. Ещё сильнее работает чувство надвигающейся беды — записки, напряжение, ожидание неизбежной катастрофы. Это один из тех детективов, где атмосфера угрозы запоминается не меньше, чем само раскрытие.', 'Иногда катастрофа начинается задолго до самого убийства.', 3.5, 3.5, 4, 4, 3.5),
  ('Карты на столе', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-05-02', 'covers/karty-na-stole.svg', '#4a6587', 'Сеттинг очень удачный: четверо подозреваемых, почти никаких улик, и каждый выглядит приличным человеком с собственными тайнами. Но книга немного разочаровывает тем, что внимание уходит не столько на Пуаро, сколько на его коллег по расследованию. Линия Энн Мередит тоже кажется недоработанной, из-за чего финальная картина выглядит слабее, чем могла бы.', 'Когда на столе лежат карты, не факт, что играешь именно ты.', 3, 3.5, 3, 3, 3),
  ('Загадка Эндхауза', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-02-04', 'covers/zagadka-endhauza.svg', '#a55662', 'Начало у романа очень удачное: Пуаро словно случайно втягивается в историю, и это сразу задаёт хороший темп. Развязка с письмами для пилота и объяснение про присвоенную историю сестры тоже интересны. Но интрига слабеет из-за того, что главная героиня начинает казаться виновной довольно рано.', 'Самая убедительная маска — та, что надевают на образ жертвы.', 3, 3, 3.5, 3.5, 3),
  ('Трагедия в трех актах', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-04-16', 'covers/tragediya-v-treh-aktah.svg', '#75543f', 'Интересно, что преступником оказывается Чарльз — человек, который сам помогает расследованию и потому кажется безопасным. Понравилась и роль Пуаро: здесь он не выходит сразу на авансцену, а будто дирижирует происходящим из-за кулис. Но мотив Чарльза ощущается натянутым, а сам финал не выстроен так, чтобы по-настоящему удивить.', 'Иногда спектакль рушится не от драмы, а от слабого последнего акта.', 2.5, 2.5, 3.5, 3, 2.5),
  ('Рождество Эркюля Пуаро', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-05-15', 'covers/rozhdestvo-erkyulya-puaro.svg', '#7a3f3f', 'Сильнее всего здесь работает атмосфера: очень разные персонажи, напряжение между родственниками и ощущение, что праздничный семейный сбор вот-вот закончится конфликтом. Хорошую динамику раскрытию братьев придают их жёны — кто-то подталкивает к поступкам, кто-то, наоборот, сдерживает из собственных мотивов. Само убийство напрашивается почти с первых страниц, после него сюжет идёт не слишком быстро, но развязка всё равно интересная: убийцей оказывается человек, о котором сперва почти не думаешь, и позднее это объясняется вполне логично.', 'Праздничный стол легко превращается в сцену для старых обид.', 3.5, 3.5, 4, 2, 4),
  ('Печальный кипарис', 'А. Кристи', 'Детективы', 'Прочитано', true, '2026-05-23', 'covers/pechalnyy-kiparis.svg', '#9b4f55', 'Очень понравилось, что история начинается с суда, а затем постепенно показывает, как всё к этому пришло. Атмосфера спокойная, но напряжение держится почти до конца: за внешней сдержанностью героев постоянно чувствуется недосказанность. Особенно хорошо работает сочетание классического расследования, личной драмы и вопроса о том, насколько очевидная вина может быть обманчивой.', 'Иногда самое тихое чувство оставляет самый глубокий след.', 4.5, 4.5, 5, 4, 4.5),
  ('Смерть на Ниле', 'А. Кристи', 'Детективы', 'Прочитано', false, '2026-05-06', 'covers/smert-na-nile.svg', '#406f8f', 'Книга не зашла: при интересной идее и хорошем потенциале повествование ощущается слишком медленным и скучным. В начале особенно тяжело держать нить: много имён, сюжет скачет от одного персонажа к другому, а сопереживать героям почти не получается. Из-за этого история кажется не цельной, а разрозненной, и дочитывать её не захотелось.', 'Даже красивое путешествие может потеряться, если история не держит курс.', 2.5, 2.5, 1, 1.5, 2.5);
